    'payload' => '{"title":{"en":"Homepage"},"slug":{"en":"homepage"},"description":{"en":null},"meta_title":{"en":null},"meta_description":{"en":null},"cmsSaveType":"update","published":true,"public":false,"publish_start_date":null,"publish_end_date":null,"languages":[{"shortlabel":"EN","label":"English","value":"en","disabled":false,"published":true}],"parent_id":0,"medias":[],"browsers":[],"blocks":[{"id":9,"type":"a17-block-hero","is_repeater":false,"editor_name":"default","content":{"title":{"en":"Generasi Muda Unggul"},"animated_words":{"en":"Berakhlak Luhur\\nBerprestasi Gemilang\\nBerilmu Tinggi"},"text":{"en":"<p>Sekolah Pusat Keunggulan yang siap membentuk lulusan berakhlak mulia, kompeten secara digital, dan siap kerja di dunia industri global.<br class=\\"softbreak\\"><\\/p>"},"badge":{"en":"SMKMUH1BLORA - Terbaik"}},"medias":{"background_image":[{"id":2,"name":"bg3.jpg","thumbnail":"https:\\/\\/smkmuh1blora.sch.id\\/img\\/93ef00db-dd65-4944-88a0-26ded5fea85c\\/bg3.jpg?fm=jpg&q=60&fit=max&dpr=1&h=256","original":"https:\\/\\/smkmuh1blora.sch.id\\/img\\/93ef00db-dd65-4944-88a0-26ded5fea85c\\/bg3.jpg","medium":"https:\\/\\/smkmuh1blora.sch.id\\/img\\/93ef00db-dd65-4944-88a0-26ded5fea85c\\/bg3.jpg?fm=jpg&q=80&fit=max&h=430","width":2816,"height":1536,"tags":[],"deleteUrl":null,"updateUrl":"https:\\/\\/smkmuh1blora.sch.id\\/admin\\/media-library\\/medias\\/single-update","updateBulkUrl":"https:\\/\\/smkmuh1blora.sch.id\\/admin\\/media-library\\/medias\\/bulk-update","deleteBulkUrl":"https:\\/\\/smkmuh1blora.sch.id\\/admin\\/media-library\\/medias\\/bulk-delete","metadatas":{"default":{"caption":null,"altText":"Bg3","video":null},"custom":{"caption":null,"altText":null,"video":null}},"pivot_id":16,"crops":{"desktop":{"pivot_id":16,"name":"desktop","width":2732,"height":1536,"x":48,"y":0}}}]},"browsers":[],"blocks":[]},{"id":10,"type":"a17-block-hero_5","is_repeater":false,"editor_name":"default","content":{"title_main":"Profil Lulusan Unggul","sub_heading":"SMK Muhammadiyah 1 Blora \\u2013 Sekolah Vokasi Rujukan Berbasis Industri","description":"SMK Muhammadiyah 1 Blora didirikan pada 10 April 1993 di bawah naungan Persyarikatan Muhammadiyah. Berlokasi strategis di Jl. Gatot Subroto Km. 1, Sonorejo, Blora, sekolah ini telah terakreditasi \\u201cUnggul\\u201d dan menjadi rujukan pendidikan vokasi di Kabupaten Blora.\\n\\nSebagai pionir, kami menghadirkan konsep Technopark\\u2014sebuah ekosistem belajar yang mengintegrasikan praktik langsung, riset terapan, dan produksi riil seperti di dunia industri. Dengan moto \\u201cSekolah Berbasis Industri,\\u201d kami memastikan setiap siswa tidak hanya mahir secara teknis, tetapi juga kuat dalam karakter Islami berlandaskan nilai-nilai Muhammadiyah.","cta_secondary_text":"#Keilmuan","cta_primary_text":"#Dedikasi","cta_primary_url":"https:\\/\\/smkmuh1blora.sch.id\\/","cta_secondary_url":"https:\\/\\/smkmuh1blora.sch.id\\/","badge_text":"Sonorejo, Blora, Jawa Tengah, 10 April 1993"},"medias":{"hero_5_image":[{"id":1,"name":"bg2.jpg","thumbnail":"https:\\/\\/smkmuh1blora.sch.id\\/img\\/93ef00db-dd65-4944-88a0-26ded5fea85c\\/bg2.jpg?fm=jpg&q=60&fit=max&dpr=1&h=256","original":"https:\\/\\/smkmuh1blora.sch.id\\/img\\/93ef00db-dd65-4944-88a0-26ded5fea85c\\/bg2.jpg","medium":"https:\\/\\/smkmuh1blora.sch.id\\/img\\/93ef00db-dd65-4944-88a0-26ded5fea85c\\/bg2.jpg?fm=jpg&q=80&fit=max&h=430","width":2816,"height":1536,"tags":[],"deleteUrl":null,"updateUrl":"https:\\/\\/smkmuh1blora.sch.id\\/admin\\/media-library\\/medias\\/single-update","updateBulkUrl":"https:\\/\\/smkmuh1blora.sch.id\\/admin\\/media-library\\/medias\\/bulk-update","deleteBulkUrl":"https:\\/\\/smkmuh1blora.sch.id\\/admin\\/media-library\\/medias\\/bulk-delete","metadatas":{"default":{"caption":null,"altText":"Bg2","video":null},"custom":{"caption":null,"altText":null,"video":null}},"pivot_id":17,"crops":{"desktop":{"pivot_id":17,"name":"desktop","width":2732,"height":1536,"x":48,"y":0}}}]},"browsers":[],"blocks":{"hero_5_i