    'payload' => '{"slug":{"en":"guru-bk-kini-bukan-lagi-polisi-sekolah-tapi-lebih-pada-upaya-berdayakan-murid"},"title":{"en":"Guru BK Kini  Bukan Lagi \\u201cPolisi Sekolah\\u201d tapi Lebih Pada Upaya Berdayakan Murid"},"published":true,"languages":[{"shortlabel":"EN","label":"English","value":"en","disabled":false,"published":true}]}',
